export type StreamlineIconWeight =
  | "thin"
  | "light"
  | "regular"
  | "bold"
  | "fill"
  | "duotone"

export interface StreamlineIconProps
  extends Omit<React.SVGProps<SVGSVGElement>, "height" | "width"> {
  height?: number | string
  size?: number | string
  weight?: StreamlineIconWeight
  width?: number | string
}

interface StreamlineIconData {
  body: string
  viewBox: string
}

function createStreamlineIcon(
  icon: StreamlineIconData,
  displayName: string,
  baseClassName?: string,
) {
  const StreamlineIcon = React.forwardRef<SVGSVGElement, StreamlineIconProps>(
    (
      {
        "aria-hidden": ariaHidden,
        "aria-label": ariaLabel,
        className,
        height,
        size,
        weight,
        width,
        ...props
      },
      ref,
    ) => {
      const resolvedWidth = width ?? size ?? "1em"
      const resolvedHeight = height ?? size ?? "1em"

      return (
        <svg
          {...props}
          ref={ref}
          xmlns="http://www.w3.org/2000/svg"
          viewBox={icon.viewBox}
          width={resolvedWidth}
          height={resolvedHeight}
          className={cn(baseClassName, className)}
          aria-hidden={ariaHidden ?? (ariaLabel ? undefined : true)}
          aria-label={ariaLabel}
          data-icon-weight={weight}
          focusable="false"
          dangerouslySetInnerHTML={{ __html: icon.body }}
        />
      )
    },
  )

  StreamlineIcon.displayName = displayName
  return StreamlineIcon
}

